INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatenames', 'Fatenames is a team-based word deduction game. Two teams, Red and Blue, compete to reveal their Fates first. Fateweavers give one-word clues that can point to multiple words on the board. Their teammates (Seekers) try to guess words of the right color while avoiding those that belong to the opposing team. And everyone wants to avoid the Disaster.' FROM games WHERE igdb_id = 379199 ON CONFLICT (game_id, language_code) DO NOTHING;
