INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circular Fallacy', 'Circular Fallacy is a narrative-driven puzzle adventure blending 2D card mechanics with immersive 3D environments. Players switch between a card table interface and first-person scenes, using a unique dice-check system to unlock branching paths and solve multi-solution puzzles. Every choice leads to different outcomes, weaving a surreal and emotionally layered story about identity, memory, and reality.' FROM games WHERE igdb_id = 362502 ON CONFLICT (game_id, language_code) DO NOTHING;
