INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Adventure: Mercury', 'Space Adventures is a thrilling platformer series that takes players on an interplanetary journey across the solar system. Each instalment is set on a different planet, introducing unique environments and innovative gameplay mechanics that evolve with every game. With 30 challenging levels per title, players must adapt to new obstacles, physics, and surprises as they sharpen their platforming skills and uncover the mysteries of the cosmos. Prepare for an ever-changing adventure where no two planets — or levels — are the same.' FROM games WHERE igdb_id = 379151 ON CONFLICT (game_id, language_code) DO NOTHING;
