INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('liminal-leap', 343432, '2025-05-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sul.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scws41.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liminal Leap', 'Liminal Leap is a pulse-pounding escape room experience set within the unsettling world of the Backrooms. Here, reality unravels, and familiar spaces morph into unrelenting, unsettling corridors. You awaken trapped within a labyrinthine facility – a twisted reflection of the everyday, now warped and hostile. Your Objective: Escape. Unravel the secrets of this insidious place and find your way back to reality. The Peril: The Lurkers: These guardians of the Backrooms manipulate the very fabric of reality. Walls shift, doors vanish, and the map you hold becomes unreliable. Stay alert! A single misstep could lead to a dead end, a trap, or worse. A Multitude of Deaths: The Backrooms are unforgiving. One wrong turn, a misstep in the dark, or a run-in with a Lurker could lead to a gruesome demise. The Challenge: Limited Saves: The first level is a harrowing gauntlet – your wits and reflexes alone will be your guide.' FROM games WHERE igdb_id = 343432 ON CONFLICT (game_id, language_code) DO NOTHING;
