INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Retail Therapy', 'Clock in. Freak out. Fight back. You’re stuck in the world’s worst shift - facing down entitled customers, absurd demands, and a mountain of workplace rage. Survive escalating chaos across restaurants, shops, and festivals, using whatever tools you can grab to keep the madness at bay.' FROM games WHERE igdb_id = 380482 ON CONFLICT (game_id, language_code) DO NOTHING;
