INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugby 25', 'Welcome to the ultimate rugby gaming experience, Rugby 25! Whether you''re a passionate fan or a newcomer to the world of rugby, Rugby 25 immerses you in the heart of the action and hard-hitting tackles like no rugby video game has before. From humble local club matches to the bright lights of the world''s greatest international tournaments, every detail has been meticulously crafted to bring the excitement and intensity of the sport to your fingertips. Rugby 25: where legends are born, and history is made.' FROM games WHERE igdb_id = 241246 ON CONFLICT (game_id, language_code) DO NOTHING;
