INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paprika x Persona False God Reincarnation', 'Dream researcher Paprika - whose real identity is Dr. Atsuko Chiba, a psychotherapist - begins experiencing vivid, unsettling nightmares. These visions include a ruined Tokyo, her former colleague transformed into the demon Amon, the enigmatic entity Philemon, and the mysterious Velvet Room. As these dreams intensify, Tokyo itself is gripped by widespread phenomena of mass hallucinations, blurring the line between dream and reality as patients’ subconscious fears leak into the waking world. To uncover the source of this phenomenon, Paprika and her intern students turn to the retro game Megami Ibunroku Persona as both a tool and a guide.' FROM games WHERE igdb_id = 386466 ON CONFLICT (game_id, language_code) DO NOTHING;
