INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Shrilow', 'Computer Shrilow is a clicker game dedicated to being actually playable! you can speak to people, gamble, try on new clothes, mine in the mines, and much more! The game also has Minigames and Events, which trigger every once in awhile, keeps you on your toes! or. paws? Theres something more going on than meets the eye however, and the only way to find out? is to play it for yourself!' FROM games WHERE igdb_id = 363679 ON CONFLICT (game_id, language_code) DO NOTHING;
