INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rabbit-run-carrot-hunt', 361347, '2025-08-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabj7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41um.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbit Run Carrot Hunt', 'Rabbit Run Carrot Hunt is a fast-paced endless runner where you play as a quick and clever rabbit trying to collect as many carrots as possible. Carrots restore your energy, which slowly depletes as you run. The longer you survive, the more points you earn. A black panther is chasing you and occasionally launches sudden attacks that you must jump over to avoid. At the same time, you need to dodge various obstacles along the way. Stay alert, keep collecting carrots, and run as far as you can before the panther catches you.' FROM games WHERE igdb_id = 361347 ON CONFLICT (game_id, language_code) DO NOTHING;
