INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouncemasters', 'Bouncemasters is a physics-based arcade launcher in which you smack an unlucky penguin skyward, then chain bounces off seals, orcas, trampolines, and other hazards to keep it airborne for as many meters and laughs as possible. Inspired by the classic YetiSports flash games, it mixes slapstick ragdoll comedy with skill-based timing, angle control, and mid-air power-ups.' FROM games WHERE igdb_id = 370674 ON CONFLICT (game_id, language_code) DO NOTHING;
