INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turn Around', 'Turn Around is an atmospheric horror game that plunges you into the darkness of the endless corridors of an abandoned building, where time and space are distorted, and rustles and creaks are heard from the shadows now and then. Your only weapon against unknown horrors is a weak torch beam. Every turn can be fatal - someone is already watching you, and if you don''t turn round in time, you risk seeing it face to face.' FROM games WHERE igdb_id = 344858 ON CONFLICT (game_id, language_code) DO NOTHING;
