INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astrumis: Survive Together', 'A two-player, sci-fi horror co‑op game set aboard an abandoned spaceship, where one player controls a lone survivor hunting for safety and the other operates the ship itself—manipulating cameras, controls, and systems to guide their partner. Together, you''ll navigate eerie corridors, solve cooperative puzzles and minigames, and evade an unseen monster stalking the ship''s depths in an atmosphere of mounting tension.' FROM games WHERE igdb_id = 350389 ON CONFLICT (game_id, language_code) DO NOTHING;
