INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blind Trust: The City', 'Blind Trust: The City is a co-op game for 2 to 5 players, where only one player can see while the others are completely “blind.” The seeing player must guide their teammates verbally through traps and obstacles. Each round demands precise communication and high trust, as any mistake restarts the team. The game is fun, intense, and relies more on teamwork and communication than visual skill.' FROM games WHERE igdb_id = 357383 ON CONFLICT (game_id, language_code) DO NOTHING;
