INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Backrooms: Maze Escape', 'Trapped in an endless maze of yellow-tinted halls and eerie silence, your only hope is to find the exit before you lose your mind. The Backrooms: Maze Escape is a first-person exploration game inspired by the viral Backrooms mythos, where every hallway looks the same and reality feels distant. Collect as many coins as possible and try to complete each level as quickly as you can. Navigate two increasingly unsettling levels with no map and no guidance - only your memory and instincts.' FROM games WHERE igdb_id = 370281 ON CONFLICT (game_id, language_code) DO NOTHING;
