INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peel a Banana', 'Welcome to the simplest yet most oddly satisfying game you''ll play today! All you have to do is click to peel a banana layer by layer. Once a banana is fully peeled, it counts as 1 banana. Then it''s on to the next one—no breaks, no limits, just endless peeling action!' FROM games WHERE igdb_id = 368557 ON CONFLICT (game_id, language_code) DO NOTHING;
