INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunting Pack', 'It’s a forest at night, and the hunt begins. Carefully plan your pack’s next move to avoid being seen, smelled or heard. Hunt enough prey to survive the next month, and develop your pack and tactics throughout changing seasons. You’ll fail – but learn from your mistakes and prepare for the next run!' FROM games WHERE igdb_id = 373309 ON CONFLICT (game_id, language_code) DO NOTHING;
